<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Может ли заказчик удержать неустойку при казначейском сопровождении?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Заказчик вправе удержать неустойку из обеспечения исполнения контракта (ст. 96 Закона № 44-ФЗ) или зачесть её из суммы оплаты (ст. 410 ГК). При казначейском сопровождении удержанная неустойка не поступает на лицевой счёт исполнителя, а направляется в доход бюджета — и только тогда обязательство считается исполненным."}}, {"@type": "Question", "name": "Нужно ли согласие исполнителя на зачёт неустойки?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Зачёт по ст. 410 ГК — односторонняя сделка: достаточно заявления заказчика. Но исполнитель должен быть уведомлён, а требование должно быть встречным, однородным и бесспорным."}}, {"@type": "Question", "name": "Можно ли оспорить удержание неустойки?", "acceptedAnswer": {"@type": "Answer", "text": "Да, если требование спорно по основанию или размеру. Президиум ВАС РФ (№ ВАС-9007/2010) указал, что зачесть в одностороннем порядке оспариваемое требование нельзя. При незаконном удержании сумму взыскивают через претензию и суд."}}, {"@type": "Question", "name": "Чем удержание неустойки отличается от её списания?", "acceptedAnswer": {"@type": "Answer", "text": "Удержание и зачёт — способ получить неустойку с исполнителя (выигрывает заказчик). Списание по Постановлению № 783 — прощение начисленного, но не уплаченного долга (выигрывает исполнитель). Это противоположные механизмы."}}, {"@type": "Question", "name": "Действует ли списание неустойки по Постановлению № 783 в 2026 году?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Постановление № 783 (ред. от 09.12.2024) продолжает действовать: Верховный Суд РФ решением от 28.05.2025 № АКПИ25-181 отказал в его отмене. При сумме до 5% цены контракта неустойка списывается полностью, при 5–20% — половина при уплате второй части."}}, {"@type": "Question", "name": "Куда уходит неустойка, удержанная при казначейском сопровождении?", "acceptedAnswer": {"@type": "Answer", "text": "В доход соответствующего бюджета. Заказчик уменьшает санкционируемую на лицевой счёт сумму на размер неустойки, а сама неустойка направляется в бюджет. На лицевой счёт исполнителя эти деньги не поступают."}}, {"@type": "Question", "name": "Можно ли списать неустойку прямо с лицевого счёта в казначействе?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Неустойка — не целевой расход по контракту, поэтому «оплатить» её как обычную операцию с лицевого счёта нельзя. Заказчик уменьшает платёж и направляет неустойку в бюджет; при гособоронзаказе действует особый режим отдельного счёта (ст. 8.3, 8.4 № 275-ФЗ)."}}, {"@type": "Question", "name": "Что делать, если заказчик удержал больше, чем сумма к оплате?", "acceptedAnswer": {"@type": "Answer", "text": "Зачётом закрывается часть неустойки в пределах суммы оплаты, а остаток заказчик взыскивает отдельно — претензией и через суд. Проверьте, чтобы к зачёту не была принята спорная часть неустойки."}}, {"@type": "Question", "name": "Как удержание неустойки связано со сроком оплаты по контракту?", "acceptedAnswer": {"@type": "Answer", "text": "Заказчик проводит зачёт при оплате принятых работ, поэтому удержание вписано в общий срок оплаты по контракту. О сроках подробно — в статье про срок оплаты по контракту 44-ФЗ."}}, {"@type": "Question", "name": "Влияет ли удержание неустойки на попадание в реестр недобросовестных поставщиков?", "acceptedAnswer": {"@type": "Answer", "text": "Само удержание неустойки — нет. Но нарушение, за которое начислена неустойка, при расторжении контракта по вине исполнителя может привести к включению в реестр недобросовестных поставщиков — это отдельная процедура."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Что делать исполнителю, если заказчик удержал неустойку", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Проверьте основание неустойки", "text": "Уточните, пеня это за просрочку или штраф за иное нарушение, по какому пункту контракта и за какой период начислено."}, {"@type": "HowToStep", "position": 2, "name": "Проверьте расчёт", "text": "Сверьте ставку и базу: пеня — не менее 1/300 ключевой ставки Банка России от неисполненной в срок суммы; штраф — по Постановлению № 1042."}, {"@type": "HowToStep", "position": 3, "name": "Найдите заявление о зачёте", "text": "Убедитесь, что заказчик письменно уведомил вас об удержании: без уведомления односторонний зачёт по ст. 410 ГК уязвим."}, {"@type": "HowToStep", "position": 4, "name": "Оцените спорность требования", "text": "Если просрочка или нарушение возникли по вине заказчика, зафиксируйте возражения — по спорному требованию односторонний зачёт неправомерен."}, {"@type": "HowToStep", "position": 5, "name": "Проверьте право на списание", "text": "Возможно, вместо удержания вам полагается списание неустойки по Постановлению № 783 — тогда требуйте применить именно его."}, {"@type": "HowToStep", "position": 6, "name": "Направьте претензию, затем иск", "text": "Если удержание незаконно, требуйте вернуть удержанное, а при отказе — взыскивайте через суд как неосновательно удержанную оплату."}]}
</script>
